// Generate a random SQL string input; ensure null-terminated C string is passed
std::string sql = FUZZ_PARAM_STR();
// Call target API
PgQueryNormalizeResult tmp = pg_query_normalize(sql.c_str());
// Persist the result for later free via pg_query_free_normalize_result
PgQueryNormalizeResult *normalize_result = new PgQueryNormalizeResult;
*normalize_result = tmp;
// Caller of free-normalize-result will handle cleanup. We do not assume success here.
// Validation: input is a valid C string; result is stored for later freeing.

// Generate a random SQL utility statement candidate
std::string sql = FUZZ_PARAM_STR();
PgQueryNormalizeResult tmp = pg_query_normalize_utility(sql.c_str());
PgQueryNormalizeResult *normalize_result = new PgQueryNormalizeResult;
*normalize_result = tmp;
// Validation: input is valid C string; result captured for later pg_query_free_normalize_result.

// Random SQL input for scanner
std::string sql = FUZZ_PARAM_STR();
PgQueryScanResult tmp = pg_query_scan(sql.c_str());
PgQueryScanResult *scan_result = new PgQueryScanResult;
*scan_result = tmp;
// Note: pbuf is opaque; consumers must use matching library tooling. Free via pg_query_free_scan_result later.

// Random SQL input for full parser
std::string sql = FUZZ_PARAM_STR();
PgQueryParseResult tmp = pg_query_parse(sql.c_str());
PgQueryParseResult *parse_result = new PgQueryParseResult;
*parse_result = tmp;
// Defer cleanup to pg_query_free_parse_result.

// Random SQL input
std::string sql = FUZZ_PARAM_STR();
// Compose parser_options: choose a valid PgQueryParseMode in the low bits (0..5). No extra flags to avoid unknown bits.
unsigned int mode = (*FUZZ_PARAM(unsigned int)) % 6; // matches PgQueryParseMode enum
int parser_options = static_cast<int>(mode);
PgQueryParseResult tmp = pg_query_parse_opts(sql.c_str(), parser_options);
PgQueryParseResult *parse_result = new PgQueryParseResult;
*parse_result = tmp;
// Cleanup deferred to pg_query_free_parse_result.

// Random SQL input for protobuf parser
std::string sql = FUZZ_PARAM_STR();
PgQueryProtobufParseResult tmp = pg_query_parse_protobuf(sql.c_str());
PgQueryProtobufParseResult *ppresult = new PgQueryProtobufParseResult;
*ppresult = tmp;
// Keep full result for later deparse/free. Free via pg_query_free_protobuf_parse_result.

// Random SQL input
std::string sql = FUZZ_PARAM_STR();
// Valid parse mode in low bits (0..5); avoid undocumented flags by leaving higher bits 0
unsigned int mode = (*FUZZ_PARAM(unsigned int)) % 6;
int parser_options = static_cast<int>(mode);
PgQueryProtobufParseResult tmp = pg_query_parse_protobuf_opts(sql.c_str(), parser_options);
PgQueryProtobufParseResult *ppresult = new PgQueryProtobufParseResult;
*ppresult = tmp;
// Cleanup deferred to pg_query_free_protobuf_parse_result.

// Random PL/pgSQL source text (arbitrary string; parser will validate)
std::string src = FUZZ_PARAM_STR();
PgQueryPlpgsqlParseResult tmp = pg_query_parse_plpgsql(src.c_str());
PgQueryPlpgsqlParseResult *plpgsql_result = new PgQueryPlpgsqlParseResult;
*plpgsql_result = tmp;
// Free later via pg_query_free_plpgsql_parse_result.

// Random SQL input for fingerprinting
std::string sql = FUZZ_PARAM_STR();
PgQueryFingerprintResult tmp = pg_query_fingerprint(sql.c_str());
PgQueryFingerprintResult *fp_result = new PgQueryFingerprintResult;
*fp_result = tmp;
// Free later via pg_query_free_fingerprint_result.

// Random SQL input
std::string sql = FUZZ_PARAM_STR();
// Only set parse mode bits (0..5) to comply with documented mask; avoid unknown flags
unsigned int mode = (*FUZZ_PARAM(unsigned int)) % 6;
int parser_options = static_cast<int>(mode);
PgQueryFingerprintResult tmp = pg_query_fingerprint_opts(sql.c_str(), parser_options);
PgQueryFingerprintResult *fp_result = new PgQueryFingerprintResult;
*fp_result = tmp;
// Cleanup via pg_query_free_fingerprint_result.

// Random SQL input for scanner-based splitting
std::string sql = FUZZ_PARAM_STR();
PgQuerySplitResult tmp = pg_query_split_with_scanner(sql.c_str());
PgQuerySplitResult *split_result = new PgQuerySplitResult;
*split_result = tmp;
// Free later via pg_query_free_split_result.

// Random SQL input for parser-based splitting
std::string sql = FUZZ_PARAM_STR();
PgQuerySplitResult tmp = pg_query_split_with_parser(sql.c_str());
PgQuerySplitResult *split_result = new PgQuerySplitResult;
*split_result = tmp;
// Cleanup deferred to pg_query_free_split_result.

// Use the parse_tree buffer inside the provided protobuf-parse result.
// Enforce that input ppresult has a plausible buffer before calling deparse.
PgQueryProtobuf parse_tree = ppresult->parse_tree;
if (parse_tree.data == nullptr || parse_tree.len == 0) {
  // If buffer isn't valid, deparsing cannot proceed.
  FUZZ_BAIL();
}
PgQueryDeparseResult tmp = pg_query_deparse_protobuf(parse_tree);
PgQueryDeparseResult *deparse_result = new PgQueryDeparseResult;
*deparse_result = tmp;
// Keep ppresult alive; ownership of parse_tree memory remains with ppresult. Free via pg_query_free_protobuf_parse_result later.
// Validation: ensures buffer non-null and non-zero length before deparsing.

// Free allocations owned by the normalize result, then delete the wrapper pointer
pg_query_free_normalize_result(*normalize_result);
// Drop the heap wrapper to avoid leaks
delete normalize_result;
// Validation: called exactly once per result; runtime ensures single-consumer semantics.

pg_query_free_scan_result(*scan_result);
delete scan_result;
// Validation: Frees pbuf.data/stderr/error; wrapper deleted to avoid leaks.

pg_query_free_parse_result(*parse_result);
delete parse_result;
// Validation: Safe single free of parse_result and wrapper.

pg_query_free_split_result(*split_result);
delete split_result;
// Validation: Frees stmts/stderr/error; wrapper deleted.

pg_query_free_deparse_result(*deparse_result);
delete deparse_result;
// Validation: Safe single free of deparse result and wrapper.

// Ensure no outstanding users of ppresult->parse_tree beyond this point.
pg_query_free_protobuf_parse_result(*ppresult);
delete ppresult;
// Validation: Frees parse_tree.data/stderr/error and deletes wrapper.

pg_query_free_plpgsql_parse_result(*plpgsql_result);
delete plpgsql_result;
// Validation: Single free; wrapper deleted.

// Free all allocations owned by the fingerprint result, then delete the wrapper pointer
pg_query_free_fingerprint_result(*fp_result);
// Drop the heap wrapper to avoid leaks and double frees via pool reuse
delete fp_result;
// Validation: Matches ownership model used by creator stub; single free and wrapper deletion prevent reuse.

// Deprecated no-op initializer; safe to call for completeness in fuzzing
pg_query_init();
// Validation: No inputs/outputs; side effects limited to optional initialization.
